const payload = $input.first().json.body ?? $input.first().json;
const recipients = payload.recipients?.whatsapp ?? [];
const santri = payload.santri ?? {};
const group = payload.group ?? {};
const ringkasan = payload.ringkasan?.baris ?? {};
const dokumen = payload.dokumen ?? {};
const event = payload.event ?? 'pendataan_baru';
const isStatusUpdate = event === 'status_verifikasi_diperbarui';
const isRevisionRequest = event === 'revisi_dokumen_diminta';

function normalizePhone(phone) {
  const raw = String(phone ?? '').replace(/[^0-9]/g, '');
  if (raw.startsWith('08')) return '62' + raw.slice(1);
  if (raw.startsWith('8')) return '62' + raw;
  return raw;
}

function roleLabel(role) {
  if (role === 'ibu') return 'Ibu';
  if (role === 'wali') return 'Bapak/Ibu Wali';
  return 'Bapak';
}

function isRevisionNeeded() {
  return isRevisionRequest
    || santri.perlu_revisi === true
    || dokumen.perlu_revisi === true
    || santri.status_pendaftaran === 'Ditolak'
    || santri.status_verifikasi === 'Ditolak';
}

function groupNoticeFor(recipient) {
  const isAkhwat = group.kelas === 'akhwat';
  if (!isAkhwat) return group.aturan ?? 'Nomor WhatsApp bapak dan ibu diperbolehkan untuk masuk grup kelas ikhwan ini.';
  if (recipient.role === 'ibu') return group.pesan_akses_ibu ?? 'Hanya nomor WhatsApp ibu yang diperbolehkan untuk masuk grup kelas akhwat ini.';
  return group.pesan_akses_ayah ?? 'Grup kelas sudah dikirim ke nomor Ibu. Yang diperbolehkan masuk grup kelas akhwat adalah nomor ibu.';
}

function groupLinkFor(recipient) {
  if (group.kelas === 'akhwat' && recipient.role !== 'ibu') return '';
  return group.link ?? '';
}

const summaryText = Object.entries(ringkasan)
  .map(([label, value]) => `- ${label}: ${value ?? '-'}`)
  .join('\n');

return recipients.map((recipient) => {
  const kelasLabel = group.kelas === 'ikhwan' ? 'ikhwan (putra)' : 'akhwat (putri)';
  const greeting = `${roleLabel(recipient.role)} ${recipient.name ?? ''}`.trim();
  const needsRevision = isRevisionNeeded();
  const revisionText = needsRevision
    ? `\n\n*Link revisi data/berkas:*\n${payload.links?.revisi ?? 'Link revisi belum tersedia. Silakan hubungi admin.'}\n\nSilakan unggah ulang hanya dokumen yang diminta oleh panitia.`
    : '';
  const statusMessage = isRevisionRequest
    ? `Assalamu'alaikum ${greeting},\n\nPanitia meminta revisi data/berkas SPSB untuk ananda *${santri.nama_lengkap ?? '-'}*.\n\n*Catatan panitia:*\n${dokumen.catatan ?? santri.pesan_status ?? '-'}\n\n*Ringkasan:*\n${summaryText}${revisionText}\n\nJazakumullah khairan.\nPanitia SPSB`
    : `Assalamu'alaikum ${greeting},\n\nStatus verifikasi data SPSB untuk ananda *${santri.nama_lengkap ?? '-'}* telah diperbarui oleh panitia.\n\n*Status terbaru:* ${santri.status_label ?? '-'}\n${santri.pesan_status ?? ''}${dokumen.catatan ? `\n\n*Catatan panitia:*\n${dokumen.catatan}` : ''}\n\n*Ringkasan:*\n${summaryText}${revisionText}\n\nCek status pendataan:\n${payload.links?.cek_status ?? '-'}\n\nJazakumullah khairan.\nPanitia SPSB`;
  const groupLink = groupLinkFor(recipient);
  const newDataMessage = `Assalamu'alaikum ${greeting},\n\nAlhamdulillah, data pendataan SPSB untuk ananda *${santri.nama_lengkap ?? '-'}* sudah masuk dan diterima oleh sistem.\n\n*Ringkasan data:*\n${summaryText}\n\n*Informasi grup kelas ${kelasLabel}:*\n${groupNoticeFor(recipient)}\n${groupLink ? `Link grup: ${groupLink}` : (group.kelas === 'akhwat' && recipient.role !== 'ibu' ? '' : 'Link grup belum tersedia. Admin akan mengirimkan link menyusul.')}\n\nTautan cetak bukti pendataan:\n${payload.links?.cetak ?? '-'}\n\nJazakumullah khairan.\nPanitia SPSB`;
  const message = (isStatusUpdate || isRevisionRequest) ? statusMessage : newDataMessage;

  return {
    json: {
      phone: normalizePhone(recipient.phone),
      role: recipient.role,
      name: recipient.name,
      event,
      message,
      payload
    }
  };
});
